import type { NextConfig } from "next";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const supabaseHost = (() => {
  try {
    return new URL(process.env.NEXT_PUBLIC_SUPABASE_URL ?? "").hostname;
  } catch {
    return null;
  }
})();

// Hashes of the landing page's inline scripts, generated by scripts/build-landing.py.
const landingScriptHashes: string[] = JSON.parse(readFileSync(join(process.cwd(), "landing", "csp.json"), "utf8")).scriptHashes;

const landingCsp = [
  "default-src 'self'",
  `script-src 'self' ${landingScriptHashes.join(" ")}`,
  "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
  "font-src 'self' data: https://fonts.gstatic.com",
  "img-src 'self' data:",
  "connect-src 'self'",
  "form-action 'self'",
  "frame-ancestors 'none'",
  "base-uri 'self'",
  "object-src 'none'",
  ...((process.env.NEXT_PUBLIC_SITE_URL ?? "").startsWith("https://") ? ["upgrade-insecure-requests"] : []),
].join("; ");

const securityHeaders = [
  { key: "X-Content-Type-Options", value: "nosniff" },
  { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
  { key: "X-Frame-Options", value: "DENY" },
  { key: "Permissions-Policy", value: "camera=(), microphone=(), geolocation=(), payment=()" },
  { key: "Cross-Origin-Opener-Policy", value: "same-origin" },
  // Browsers ignore HSTS on plain-http localhost, so it is safe in development too.
  { key: "Strict-Transport-Security", value: "max-age=63072000; includeSubDomains" },
];

const nextConfig: NextConfig = {
  poweredByHeader: false,
  // The original landing page is served as a static file at "/".
  async rewrites() {
    return { beforeFiles: [{ source: "/", destination: "/landing.html" }], afterFiles: [], fallback: [] };
  },
  images: {
    remotePatterns: supabaseHost
      ? [
          {
            protocol: supabaseHost === "127.0.0.1" || supabaseHost === "localhost" ? "http" : "https",
            hostname: supabaseHost,
            pathname: "/storage/v1/object/public/**",
          },
        ]
      : [],
  },
  async headers() {
    return [
      { source: "/:path*", headers: securityHeaders },
      // App pages get a per-request nonce CSP from the middleware.
      { source: "/", headers: [{ key: "Content-Security-Policy", value: landingCsp }] },
      { source: "/landing.html", headers: [{ key: "Content-Security-Policy", value: landingCsp }] },
    ];
  },
};

export default nextConfig;
